/**
 * 스킬 아이콘 — 전부 실제로 존재하는 공개 아이콘에서 가져왔다(직접 그린 글리프
 * 없음). 대부분은 simple-icons(공식 브랜드 컬러 SVG), SQL·데이터 가용성 설계는
 * 설명에 실제로 등장하는 기술(PostgreSQL·JSON)의 공식 로고로 대체했고,
 * Zustand는 공식 브랜드 SVG가 devicon(pmndrs 곰 일러스트)뿐이라 그걸 그대로
 * 가져와 22px 뱃지에 맞게 소수점을 줄여 압축했다(다소 뭉개짐 감수).
 * 결제·SMS 인증 / AI 기록은 회사명이 아니라 직접 붙인 개념 라벨이라 대응되는
 * 브랜드가 없어 자체 제작 글리프를 그대로 둔다(사용자 확인 완료).
 * skills.ts 의 항목 이름과 정확히 일치하는 키로 찾는다 (SkillsSection.tsx 참고).
 */

export type SkillIcon = {
  viewBox: string;
  /** 원본 SVG의 <path>/<text> 내부 마크업 */
  inner: string;
  color: string;
};

